  <style>
    * { margin: 0; padding: 0; box-sizing: border-box; }
    body { font-family: 'Inter', system-ui, sans-serif; color: #231F20; }

    /* Stats Ticker */
    @keyframes ticker-scroll {
      0% { transform: translateX(0); }
      100% { transform: translateX(-50%); }
    }
    .ticker-track {
      display: flex;
      animation: ticker-scroll 20s linear infinite;
      width: max-content;
    }
    .ticker-track:hover { animation-play-state: paused; }

    /* Mega Menu */
    .nav-item:hover .mega-menu,
    .nav-item:focus-within .mega-menu {
      opacity: 1;
      visibility: visible;
      transform: translateY(0);
    }
    .mega-menu {
      opacity: 0;
      visibility: hidden;
      transform: translateY(8px);
      transition: all 200ms ease-out;
    }

    /* Health Topics Carousel */
    .topics-scroll {
      scroll-behavior: smooth;
      -ms-overflow-style: none;
      scrollbar-width: none;
    }
    .topics-scroll::-webkit-scrollbar { display: none; }

    /* Tab underline */
    .tab-btn { position: relative; }
    .tab-btn::after {
      content: '';
      position: absolute;
      bottom: -2px;
      left: 0;
      width: 0;
      height: 2px;
      background: #02838d;
      transition: width 200ms ease-out;
    }
    .tab-btn.active::after,
    .tab-btn:hover::after { width: 100%; }

    /* Article card hover */
    .article-card {
      transition: transform 200ms ease-out, box-shadow 200ms ease-out;
    }
    .article-card:hover {
      transform: translateY(-4px);
      box-shadow: 0 12px 24px rgba(0,0,0,0.08);
    }

    /* Video play button pulse */
    @keyframes pulse-ring {
      0% { transform: scale(1); opacity: 0.6; }
      100% { transform: scale(1.5); opacity: 0; }
    }
    .play-btn-pulse::before {
      content: '';
      position: absolute;
      inset: -6px;
      border-radius: 50%;
      background: rgba(2, 131, 141, 0.3);
      animation: pulse-ring 2s ease-out infinite;
    }

    /* Smooth entry animations */
    @keyframes fadeInUp {
      from { opacity: 0; transform: translateY(20px); }
      to { opacity: 1; transform: translateY(0); }
    }
    .animate-in {
      animation: fadeInUp 500ms ease-out forwards;
    }

    /* Toast notification */
    @keyframes slideInRight {
      from { transform: translateX(120%); opacity: 0; }
      to { transform: translateX(0); opacity: 1; }
    }
    @keyframes slideOutRight {
      from { transform: translateX(0); opacity: 1; }
      to { transform: translateX(120%); opacity: 0; }
    }
    .toast-in { animation: slideInRight 300ms ease-out forwards; }
    .toast-out { animation: slideOutRight 300ms ease-in forwards; }

    /* Trust pillar icon hover */
    .trust-card:hover .trust-icon {
      transform: scale(1.08);
      transition: transform 200ms ease-out;
    }
    .trust-icon { transition: transform 200ms ease-out; }

    /* Mobile menu */
    .mobile-menu {
      max-height: 0;
      overflow: hidden;
      transition: max-height 300ms ease-out;
    }
    .mobile-menu.open { max-height: 1000px; }
    .mobile-sub { max-height: 0; overflow: hidden; transition: max-height 200ms ease-out; }
    .mobile-sub.open { max-height: 500px; }
  </style>
