    // ---- Newsletter Form Handler ----
    function handleNewsletter(event, form, btnText) {
      event.preventDefault();
      const emailInput = form.querySelector('input[type="email"]');
      const email = emailInput.value.trim();
      if (email) {
        showToast(`Thanks for signing up! We'll send wellness tips to ${email}`);
        emailInput.value = '';
      }
    }

    // ---- Toast Notification ----
    function showToast(message) {
      const container = document.getElementById('toast-container');
      const toast = document.createElement('div');
      toast.className = 'toast-in bg-teal-600 text-white px-5 py-3 rounded-xl shadow-lg text-sm font-medium max-w-sm flex items-center gap-3';
      toast.innerHTML = `<i data-lucide="check-circle" class="w-5 h-5 flex-shrink-0"></i><span>${message}</span>`;
      container.appendChild(toast);
      lucide.createIcons({ nodes: [toast] });

